{
    public const STATES=['PENDING','WAITING_PICKUP','PICKED_UP','RUNNING','COMPLETED','CANCELLED'];
    public function __construct(private PDO $db){}
    private function query(string $sql,array $args=[]):PDOStatement{$q=$this->db->prepare($sql);$q->execute($args);return $q;}
    private static function bad(string $message='Thông tin đặt xe không hợp lệ.'):never{throw new HttpError(400,$message);}
    private static function keys(array $in,array $keys):void{if(array_diff(array_keys($in),$keys))self::bad();}
    private static function text(mixed $v,int $min,int $max,bool $trim=true):string{if(!is_string($v)||str_contains($v,"\0"))self::bad();if($trim)$v=preg_replace('/^[\s\x{FEFF}]+|[\s\x{FEFF}]+$/u','',$v);if($v===null)self::bad();$n=strlen(mb_convert_encoding($v,'UTF-16LE','UTF-8'))/2;if($n<$min||$n>$max)self::bad();return $v;}
    private static function num(mixed $v,int $min,int $max):int{if(!is_int($v)||$v<$min||$v>$max)self::bad();return $v;}
    private static function uuid(mixed $v):string{if(!is_string($v)||!preg_match('/^[a-f0-9]{8}-[a-f0-9]{4}-[1-8][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/iD',$v))self::bad();return strtolower($v);}
    private static function uid():string{$h=bin2hex(random_bytes(16));return substr($h,0,8).'-'.substr($h,8,4).'-4'.substr($h,13,3).'-'.dechex(8+hexdec($h[16])%4).substr($h,17,3).'-'.substr($h,20);}
    private static function clock(mixed $v):string{if(!is_string($v)||!preg_match('/^(?:[01][0-9]|2[0-3]):[0-5][0-9]$/D',$v))self::bad();return $v;}
    public static function checkDate(string $date,string $time,?int $now=null):void{StaySchema::date($date);self::clock($time);$at=(new DateTimeImmutable($date.'T'.$time.':00+07:00'))->getTimestamp();if($at<=($now??time())+1800)self::bad('Chọn ngày giờ hợp lệ, trước giờ đi ít nhất 30 phút.');}
    public static function fare(array $q,bool $roundTrip=false):?array{$isReturn=($q['roundTripOnly']??false)||$roundTrip;if(!$isReturn)return ['total'=>$q['total'],'roundTrip'=>false];$price=($q['roundTripOnly']??false)?($q['base']??0):2*($q['base']??0);return !$price?null:['total'=>$price+2*($q['surcharge']??0),'roundTrip'=>true];}
    private static function route(array $in,bool $booking=false):array
    {
        self::keys($in,['roundTrip','from','to','passengers','date','time','flexMinutes','mode','locale',...($booking?['returnTime','payment','shareSize','poolId','requestKey','vehicleId','expectedTotal','contact','pickup','dropoff','note']:[])]);
        if(($in['mode']??null)!=='PRIVATE')self::bad('Đợt này chỉ nhận xe riêng.');$out=['from'=>self::text($in['from']??null,1,80,false),'to'=>self::text($in['to']??null,1,80,false),'passengers'=>self::num($in['passengers']??null,1,60),'date'=>StaySchema::date($in['date']??null),'time'=>self::clock($in['time']??null),'flexMinutes'=>self::num($in['flexMinutes']??null,0,60),'mode'=>'PRIVATE'];if(!in_array($out['flexMinutes'],[0,30,60],true))self::bad();
        if(array_key_exists('roundTrip',$in)){if(!is_bool($in['roundTrip']))self::bad();$out['roundTrip']=$in['roundTrip'];}if(array_key_exists('locale',$in)){if(!in_array($in['locale'],['vi','en'],true))self::bad();$out['locale']=$in['locale'];}return $out;
    }
    private function plan():array{return (new TransportPlan($this->db))->read()['plan'];}
    public function catalog():array
    {
        $p=$this->plan();$endpoints=[];foreach($p['fares'] as $f)if($f['privatePrice']>0){$endpoints[$f['from']]=true;$endpoints[$f['to']]=true;}$areas=[];if($p['enabled'])foreach($p['areas'] as $a)if(array_intersect(TransportPlan::ancestors($p,$a['id']),array_keys($endpoints)))$areas[]=array_intersect_key($a,array_flip(['id','name','englishName','aliases','parentId']));return ['data'=>['enabled'=>$p['enabled'],'qrEnabled'=>false,'modes'=>['PRIVATE'],'sharedScopes'=>[],'areas'=>$areas]];
    }
    private function offers(array $p,array $in):array
    {
        self::checkDate($in['date'],$in['time']);if(!$p['enabled'])return [];$out=[];foreach(TransportPlan::quotes($p,$in['from'],$in['to'],$in['passengers']) as $q){if(isset($q['error'])||($q['base']??0)<=0)continue;$fare=self::fare($q,$in['roundTrip']??false);if(!$fare||$fare['total']<=0)continue;$v=array_column($p['vehicles'],null,'id')[$q['vehicleId']];$en=($in['locale']??'vi')==='en';$out[]=['vehicleId'=>$v['id'],'name'=>$en?(($v['englishName']??'')!==''?$v['englishName']:$v['name']):$v['name'],'seats'=>$v['seats'],'image'=>$v['image']??null,'note'=>$en?(($p['noteEn']??'')!==''?$p['noteEn']:($p['note']??'')):($p['note']??$v['luggageNote']),'durationMinutes'=>$q['durationMinutes']??null,...$fare,'shareSize'=>null,'poolId'=>null];}return $out;
    }
    public function quotes(array $in):array{return ['data'=>$this->offers($this->plan(),self::route($in))];}
    private static function booking(array $in):array
    {
        $out=self::route($in,true);$out['requestKey']=self::uuid($in['requestKey']??null);$out['vehicleId']=self::text($in['vehicleId']??null,1,80,false);$out['expectedTotal']=self::num($in['expectedTotal']??null,0,9007199254740991);
        if(($in['payment']??'PAY_LATER')!=='PAY_LATER'||array_key_exists('payment',$in)&&$in['payment']===null)self::bad('Chưa mở thanh toán QR cho đơn xe.');$out['payment']='PAY_LATER';if(array_key_exists('shareSize',$in)||array_key_exists('poolId',$in))self::bad('Xe riêng không dùng nhóm ghép.');
        $c=$in['contact']??null;if(!is_array($c))self::bad();self::keys($c,['name','phone','email']);$phone=self::text($c['phone']??null,8,25);$email=self::text($c['email']??null,1,200,false);if(!preg_match('/^\+?[0-9 ()-]{8,25}$/D',$phone)||!filter_var($email,FILTER_VALIDATE_EMAIL))self::bad('Kiểm tra điện thoại và email.');$out['contact']=['name'=>self::text($c['name']??null,2,120),'phone'=>$phone,'email'=>$email];foreach(['pickup','dropoff'] as $k)$out[$k]=self::text($in[$k]??null,3,300);$out['note']=self::text(array_key_exists('note',$in)?$in['note']:'',0,1000);if(array_key_exists('returnTime',$in))$out['returnTime']=self::clock($in['returnTime']);return $out;
    }
    private function transaction(callable $work):array{$this->db->exec('SET TRANSACTION ISOLATION LEVEL READ COMMITTED');$this->db->beginTransaction();try{if(!$this->query("SELECT id FROM jingo_catalog_locks WHERE id='catalog' FOR UPDATE")->fetchColumn())throw new HttpError(503,'Chưa cài khóa danh mục.');$out=$work();$this->db->commit();return $out;}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}}
    public function create(array $body):array
    {
        $in=self::booking($body);$hash=hash('sha256',json_encode($in,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR));return $this->transaction(function()use($in,$hash){$old=$this->query('SELECT code,data FROM jingo_ride_bookings WHERE request_key=?',[$in['requestKey']])->fetch(PDO::FETCH_ASSOC);if($old){if(json_decode($old['data'],true,512,JSON_THROW_ON_ERROR)['requestHash']!==$hash)throw new HttpError(409,'Yêu cầu đã được sử dụng. Tạo lại yêu cầu mới.');return ['code'=>$old['code']];}
            $p=$this->plan();$options=$this->offers($p,$in);$quote=null;foreach($options as $q)if($q['vehicleId']===$in['vehicleId']){$quote=$q;break;}if(!$quote||$quote['total']!==$in['expectedTotal'])throw new HttpError(409,'Giá hoặc cấu hình vừa thay đổi. Vui lòng tìm xe lại.');if(isset($in['returnTime'])&&(!$quote['roundTrip']||$in['returnTime']<=$in['time']))self::bad('Giờ về phải sau giờ đi trong cùng ngày; chỉ áp dụng cho chuyến khứ hồi.');
            $id=self::uid();$code='JM-X'.strtoupper(bin2hex(random_bytes(6)));$data=$in;unset($data['requestKey'],$data['expectedTotal']);$areas=array_column($p['areas'],null,'id');$data=array_replace($data,['roundTrip'=>$quote['roundTrip'],'autoPool'=>false,'shareSize'=>null,'total'=>$quote['total'],'vehicleName'=>$quote['name'],'vehicleNote'=>$quote['note'],'durationMinutes'=>$quote['durationMinutes'],'fromName'=>$areas[$in['from']]['name'],'toName'=>$areas[$in['to']]['name'],'requestHash'=>$hash,'paymentStatus'=>'UNPAID','driver'=>'','driverPhone'=>'','plate'=>'']);$this->query('INSERT INTO jingo_ride_bookings(id,code,request_key,visit_date,status,trip_id,data) VALUES (?,?,?,?,?,NULL,?)',[$id,$code,$in['requestKey'],$in['date'],'PENDING',json_encode($data,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR)]);(new Notifications($this->db))->enqueue('CAR',$code);return ['code'=>$code];});
    }
    public function status(array $in):array
    {
        self::keys($in,['code','requestKey']);$code=$in['code']??null;if(!is_string($code)||!preg_match('/^JM-X[A-F0-9]{12}$/D',$code))self::bad();$key=self::uuid($in['requestKey']??null);$row=$this->query('SELECT status,data FROM jingo_ride_bookings WHERE code=? AND request_key=?',[$code,$key])->fetch(PDO::FETCH_ASSOC);if(!$row)throw new HttpError(404,'Không tìm thấy booking.');$d=json_decode($row['data'],true,512,JSON_THROW_ON_ERROR);$out=['status'=>$row['status'],'roundTrip'=>$d['roundTrip']??false,'total'=>$d['total'],'paymentStatus'=>$d['paymentStatus']??'UNPAID','paidAmount'=>$d['paidAmount']??0,'pool'=>null];if(isset($d['returnTime']))$out['returnTime']=$d['returnTime'];return $out;
    }
    public function list(array $in):array
    {
        self::keys($in,['date','status','page']);$date=$in['date']??'';$status=$in['status']??'';if(!is_string($date)||!is_string($status))self::bad();if($date!=='')StaySchema::date($date);if($status!==''&&!in_array($status,self::STATES,true))self::bad();$page=$in['page']??'1';if(!is_string($page)||!preg_match('/^[1-9][0-9]{0,5}$/D',$page)||(int)$page>100000)self::bad();$where=[];$args=[];if($date!==''){$where[]='visit_date=?';$args[]=$date;}if($status!==''){$where[]='status=?';$args[]=$status;}$w=$where?' WHERE '.implode(' AND ',$where):'';$total=(int)$this->query('SELECT COUNT(*) FROM jingo_ride_bookings'.$w,$args)->fetchColumn();$rows=$this->query('SELECT id,code,visit_date,status,trip_id,data,version,created_at FROM jingo_ride_bookings'.$w.' ORDER BY created_at DESC,id DESC LIMIT 50 OFFSET '.(((int)$page-1)*50),$args)->fetchAll(PDO::FETCH_ASSOC);foreach($rows as &$r){$r['data']=json_decode($r['data'],true,512,JSON_THROW_ON_ERROR);unset($r['data']['requestHash']);$r['version']=(int)$r['version'];}return ['data'=>$rows,'total'=>$total,'page'=>(int)$page];
    }
    public function update(string $id,array $in,string $actor):array
    {
        $id=self::uuid($id);self::keys($in,['version','status','tripId','driver','driverPhone','plate','operatorNote']);$version=self::num($in['version']??null,1,2147483646);$status=$in['status']??null;if(!in_array($status,self::STATES,true))self::bad();if(($in['tripId']??null)!==null)self::bad('Xe riêng không gán chuyến ghép.');$data=[];foreach(['driver'=>120,'driverPhone'=>25,'plate'=>30,'operatorNote'=>1000] as $k=>$max)$data[$k]=self::text($in[$k]??null,0,$max);
        return $this->transaction(function()use($id,$version,$status,$data,$actor){$r=$this->query('SELECT * FROM jingo_ride_bookings WHERE id=? FOR UPDATE',[$id])->fetch(PDO::FETCH_ASSOC);if(!$r)throw new HttpError(404,'Không tìm thấy đơn xe.');if((int)$r['version']!==$version)throw new HttpError(409,'Booking vừa thay đổi. Tải lại bảng.');$d=json_decode($r['data'],true,512,JSON_THROW_ON_ERROR);if(($d['mode']??null)!=='PRIVATE'||($d['autoPool']??false))throw new HttpError(409,'Chưa hỗ trợ xử lý đơn ghép.');$next=['PENDING'=>['PENDING','WAITING_PICKUP','CANCELLED'],'WAITING_PICKUP'=>['WAITING_PICKUP','PICKED_UP','CANCELLED'],'PICKED_UP'=>['PICKED_UP','RUNNING','CANCELLED'],'RUNNING'=>['RUNNING','COMPLETED'],'COMPLETED'=>[],'CANCELLED'=>[]];if(!in_array($status,$next[$r['status']]??[],true))throw new HttpError(409,'Chuyển trạng thái không hợp lệ.');if(in_array($status,['WAITING_PICKUP','PICKED_UP','RUNNING'],true)&&($data['driver']===''||!preg_match('/^\+?[0-9 ()-]{8,25}$/D',$data['driverPhone'])||$data['plate']===''))self::bad('Cần tài xế, số điện thoại và biển số trước khi đón khách.');$this->query('UPDATE jingo_ride_bookings SET status=?,trip_id=NULL,data=?,version=version+1 WHERE id=?',[$status,json_encode(array_replace($d,$data),JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),$id]);$this->query('INSERT INTO jingo_audit(id,admin_id,action,entity_id) VALUES (?,?,?,?)',[bin2hex(random_bytes(16)),$actor,'ride.'.strtolower($status),$id]);return ['ok'=>true];});
    }
}
